    for (; i < n; i++) {
      const c = chunk.charCodeAt(i);
      switch (state) {
        case FIELD_START:
          if (c === LF && afterCR) {
            afterCR = false;
            continue;
          }
          if (fields.length === 0) recordLine = line;
          fieldLine = line;
          fieldColumn = column;
          if (c === QUOTE) {
            state = QUOTED;
            value = '';
            segment = i + 1;
          } else if (c === delimiter) {
            endField('');
          } else if (c === CR || c === LF) {
            // With no fields yet, this line is empty.
            if (fields.length > 0 || !skipEmptyLines) {
              endField('');
              endRecord();
            }
          } else {
            state = UNQUOTED;
            value = '';
            segment = i;
          }
          break;
        case UNQUOTED:
          if (c === delimiter) {
            endField(value + chunk.slice(segment, i));
            state = FIELD_START;
          } else if (c === CR || c === LF) {
            endField(value + chunk.slice(segment, i));
            endRecord();
            state = FIELD_START;
          }
          break;
        case QUOTED:
          if (c === QUOTE) {
            value += chunk.slice(segment, i);
            state = QUOTE_IN_QUOTED;
          }
          break;
        default: // QUOTE_IN_QUOTED
          if (c === QUOTE) {
            // An escaped quote: the second one starts the next run of text.
            state = QUOTED;
            segment = i;
          } else if (c === delimiter) {
            endField(value);
            state = FIELD_START;
          } else if (c === CR || c === LF) {
            endField(value);
            endRecord();
            state = FIELD_START;
          } else {
            throw new CsvError('Unexpected character after closing quote', line, column);
          }
      }
      if (c === CR) {
        line++;
        column = 1;
        afterCR = true;
      } else if (c === LF) {
        if (afterCR) {
          afterCR = false;
        } else {
          line++;
          column = 1;
        }
      } else {
        column++;
        afterCR = false;
      }
    }
    if (state === UNQUOTED || state === QUOTED) value += chunk.slice(segment, n);
    return take();
  }

  function end() {
    if (state === QUOTED) {
      throw new CsvError('Unclosed quoted field', fieldLine, fieldColumn);
    }
    if (state !== FIELD_START) {
      endField(value);
      endRecord();
    } else if (fields.length > 0) {
      // The input ends right after a delimiter: the last field is empty.
      fieldLine = line;
      fieldColumn = column;
      endField('');
      endRecord();
    }
    return take();
  }

  return { write, end };
}

function parse(text, options = {}) {
  if (typeof text !== 'string') throw new TypeError('text must be a string');
  const core = createCore(options);
  const records = core.write(text);
  for (const record of core.end()) records.push(record);
  return records;
}

function createParser(options = {}) {
  const core = createCore(options);
  let finished = false;

  function checkNotFinished() {
    if (finished) throw new Error('The parser has already finished');
  }

  return {
    write(chunk) {
      checkNotFinished();
      try {
        if (typeof chunk !== 'string') throw new TypeError('chunk must be a string');
        return core.write(chunk);
      } catch (error) {
        finished = true;
        throw error;
      }
    },
    end() {
      checkNotFinished();
      finished = true;
      return core.end();
    },
  };
}

function getEol(options) {
  const { eol } = options;
  if (eol === undefined) return '\r\n';
  if (eol !== '\r\n' && eol !== '\n') throw new TypeError('eol must be "\\r\\n" or "\\n"');
  return eol;
}

function getHeader(options) {
  const { header } = options;
  if (header === undefined || header === null || header === false) return null;
  if (!Array.isArray(header)) throw new TypeError('header must be an array of column names');
  for (let k = 0; k < header.length; k++) {
    if (typeof header[k] !== 'string') throw new TypeError('column names must be strings');
  }
  return header;
}

function toText(value) {
  if (typeof value === 'string') return value;
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  if (value === null || value === undefined) return '';
  throw new TypeError(`Cannot write a value of type ${typeof value}`);
}

function formatField(text, delimiter, forceQuote) {
  const n = text.length;
  let quote = forceQuote || (n > 0 && (text.charCodeAt(0) === SPACE || text.charCodeAt(n - 1) === SPACE));
  for (let k = 0; !quote && k < n; k++) {
    const c = text.charCodeAt(k);
    quote = c === delimiter || c === QUOTE || c === CR || c === LF;
  }
