'use strict';

const { createParser, CsvError } = require('../src/csv');

// Deterministic PRNG (mulberry32) so failures are reproducible.
function random(seed) {
  let a = seed >>> 0;
  return function next() {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function randomString(rand, alphabet, maxLength) {
  const length = Math.floor(rand() * (maxLength + 1));
  let s = '';
  for (let k = 0; k < length; k++) s += alphabet[Math.floor(rand() * alphabet.length)];
  return s;
}

// Runs fn and describes what happened, so results and CsvErrors can be compared.
function outcome(fn) {
  try {
    return { records: fn() };
  } catch (error) {
    if (!(error instanceof CsvError)) throw error;
    return { error: { line: error.line, column: error.column } };
  }
}

function parseChunks(chunks, options) {
  const parser = createParser(options);
  const records = [];
  for (const chunk of chunks) records.push(...parser.write(chunk));
  records.push(...parser.end());
  return records;
}

// An independent, deliberately simple implementation of the parsing rules,
// used as an oracle: it scans the whole string with indexOf and computes
// positions from string offsets instead of tracking them incrementally.
function referenceParse(text, options = {}) {
  const delimiter = options.delimiter === undefined ? ',' : options.delimiter;
  const start = text.charCodeAt(0) === 0xfeff ? 1 : 0;
  const n = text.length;
  const isBreak = (i) => text[i] === '\r' || text[i] === '\n';
  const fail = (index) => {
    const lines = text.slice(start, index).split(/\r\n|\r|\n/);
    throw new CsvError('reference', lines.length, lines[lines.length - 1].length + 1);
  };
  const records = [];
  let columns = null;
  const addRecord = (fields, index) => {
    if (!options.header) records.push(fields);
    else if (columns === null) columns = fields;
    else if (fields.length !== columns.length) fail(index);
    else records.push(Object.fromEntries(columns.map((name, k) => [name, fields[k]])));
  };

  let i = start;
  while (i < n) {
    const recordStart = i;
    const fields = [];
    if (isBreak(i)) {
      if (!options.skipEmptyLines) addRecord([''], recordStart);
    } else {
      for (;;) {
        const fieldStart = i;
        let value = '';
        if (text[i] === '"') {
          let from = i + 1;
          for (;;) {
            const close = text.indexOf('"', from);
            if (close === -1) fail(fieldStart);
            value += text.slice(from, close);
            if (text[close + 1] === '"') {
              value += '"';
              from = close + 2;
            } else {
              i = close + 1;
              break;
            }
          }
          if (i < n && text[i] !== delimiter && !isBreak(i)) fail(i);
        } else {
          let end = i;
          while (end < n && text[end] !== delimiter && !isBreak(end)) end++;
          value = text.slice(i, end);
          i = end;
        }
        if (options.header && columns === null && fields.includes(value)) fail(fieldStart);
        fields.push(value);
        if (text[i] !== delimiter) break;
        i++;
      }
      addRecord(fields, recordStart);
    }
    if (i < n) i += text[i] === '\r' && text[i + 1] === '\n' ? 2 : 1;
  }
  return records;
}

module.exports = { random, randomString, outcome, parseChunks, referenceParse };

