'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { parse, createParser, CsvError } = require('../src/csv');
const { random, randomString, outcome, parseChunks } = require('./helpers');

function assertFinished(parser) {
  const isPlainError = (error) => error instanceof Error && !(error instanceof CsvError);
  assert.throws(() => parser.write('a'), isPlainError);
  assert.throws(() => parser.end(), isPlainError);
}

test('returns each record from the write whose chunk ends it', () => {
  const parser = createParser();
  assert.deepEqual(parser.write('a,b'), []);
  assert.deepEqual(parser.write(',c\nd,e\nf'), [['a', 'b', 'c'], ['d', 'e']]);
  assert.deepEqual(parser.write(''), []);
  assert.deepEqual(parser.write('\n\n'), [['f'], ['']]);
  assert.deepEqual(parser.write('g'), []);
  assert.deepEqual(parser.end(), [['g']]);
});

test('a record ended by a CR is returned before the LF arrives', () => {
  const parser = createParser();
  assert.deepEqual(parser.write('a\r'), [['a']]);
  assert.deepEqual(parser.write('\nb\r'), [['b']]);
  assert.deepEqual(parser.write('\r'), [['']]);
  assert.deepEqual(parser.end(), []);
});

test('end returns nothing after a final line break', () => {
  const parser = createParser();
  assert.deepEqual(parser.write('a\n'), [['a']]);
  assert.deepEqual(parser.end(), []);
});

test('an empty stream gives no records', () => {
  assert.deepEqual(createParser().end(), []);
  const parser = createParser({ header: true });
  assert.deepEqual(parser.write(''), []);
  assert.deepEqual(parser.end(), []);
});

test('header mode does not return the header record', () => {
  const parser = createParser({ header: true });
  assert.deepEqual(parser.write('x,y\n1'), []);
  assert.deepEqual(parser.write(',2\n3,4'), [{ x: '1', y: '2' }]);
  assert.deepEqual(parser.end(), [{ x: '3', y: '4' }]);
});

test('a byte order mark is ignored only at the start of the stream', () => {
  assert.deepEqual(parseChunks(['', '﻿', 'a', '﻿b']), [['a﻿b']]);
  assert.deepEqual(parseChunks(['a', '﻿']), [['a﻿']]);
});

test('validates options when created', () => {
  assert.throws(() => createParser({ delimiter: '"' }), TypeError);
  assert.throws(() => createParser({ delimiter: '' }), TypeError);
  assert.throws(() => createParser(null), TypeError);
});

test('write requires a string, and a failed write finishes the parser', () => {
  for (const chunk of [undefined, null, 1, Buffer.from('a')]) {
    const parser = createParser();
    assert.throws(() => parser.write(chunk), TypeError);
    assertFinished(parser);
  }
});

test('both methods throw after end', () => {
  const parser = createParser();
  parser.write('a');
  parser.end();
  assertFinished(parser);
});

test('both methods throw after a CsvError from write', () => {
  const parser = createParser();
  assert.throws(() => parser.write('"a"b'), CsvError);
  assertFinished(parser);
});

test('both methods throw after a CsvError from end', () => {
  const parser = createParser();
  assert.deepEqual(parser.write('"a'), []);
  assert.throws(() => parser.end(), CsvError);
  assertFinished(parser);
});

const corpus = [
  '',
  '\n',
  '\r\n',
  '\r\r\n\n',
  'a,b\r\nc,d',
  'a,b\r\nc,d\r\n',
  'a\rb\nc\r\nd\n\re',
  '﻿a,b\n',
  '﻿"x"y',
  '"a""b",c\r\n"d\r\ne","f\rg"\n',
  '"",""""\n""',
  'a"b,"c""d"\r\n',
  '"a"b',
  '"a"""',
  'a,"b',
  '"a\r\nb\r\n',
  '\n\na\n\n\nb\n\n',
  'h1,h2\r\n1,2\r\n3,4\r\n',
  'h1,h2\n1,2,3\n',
  'h,h\n',
  'a,"b\r\nc","b\r\nc"\n',
  'a,a,"b',
  'a,b\n1,2,"x"y',
  ' a ; "b;c" ;d\n;',
  '😀,"é"x',
];

const optionSets = [
  {},
  { skipEmptyLines: true },
  { header: true },
  { header: true, skipEmptyLines: true },
  { delimiter: ';' },
];

test('gives the same result as parse for every split into up to three chunks', () => {
  for (const text of corpus) {
    for (const options of optionSets) {
      const expected = outcome(() => parse(text, options));
      const message = `${JSON.stringify(text)} with ${JSON.stringify(options)}`;
      assert.deepEqual(outcome(() => parseChunks([text], options)), expected, message);
      assert.deepEqual(outcome(() => parseChunks([...text], options)), expected, message);
      for (let i = 0; i <= text.length; i++) {
        for (let j = i; j <= text.length; j++) {
          const chunks = [text.slice(0, i), text.slice(i, j), text.slice(j)];
          assert.deepEqual(outcome(() => parseChunks(chunks, options)), expected, `${message} split at ${i}, ${j}`);
        }
      }
    }
  }
});

test('gives the same result as parse for random input and random chunks', () => {
  const rand = random(2);
