'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { parse, stringify } = require('../src/csv');
const { random, randomString } = require('./helpers');

test('writes records joined and ended by CRLF', () => {
  assert.equal(stringify([['a', 'b'], ['c', 'd']]), 'a,b\r\nc,d\r\n');
  assert.equal(stringify([['a']]), 'a\r\n');
});

test('no rows gives an empty string', () => {
  assert.equal(stringify([]), '');
  assert.equal(stringify([], { eol: '\n' }), '');
});

test('rows must be an array of arrays', () => {
  for (const rows of [undefined, null, 'a', {}, 1]) {
    assert.throws(() => stringify(rows), TypeError);
  }
  for (const row of [null, 'a,b', { a: 1 }, 1]) {
    assert.throws(() => stringify([row]), TypeError);
  }
  assert.throws(() => stringify([['a']], null), TypeError);
});

test('converts values', () => {
  assert.equal(stringify([['s', 1, -2.5, 0, NaN, true, false, null, undefined]]), 's,1,-2.5,0,NaN,true,false,,\r\n');
  assert.equal(stringify([[1e21]]), '1e+21\r\n');
  assert.equal(stringify([[, 'x']]), ',x\r\n'); // eslint-disable-line no-sparse-arrays
});

test('rejects values of other types', () => {
  for (const value of [{}, [], new Date(0), Symbol('s'), 1n, () => {}, new String('s')]) {
    assert.throws(() => stringify([[value]]), TypeError, String(typeof value));
  }
});

test('quotes fields that need it and doubles their quotes', () => {
  assert.equal(stringify([['a,b', 'c"d', 'e\rf', 'g\nh', 'i\r\nj']]), '"a,b","c""d","e\rf","g\nh","i\r\nj"\r\n');
  assert.equal(stringify([[' a', 'b ', ' ', 'c d', '\te\t']]), '" a","b "," ",c d,\te\t\r\n');
  assert.equal(stringify([['"']]), '""""\r\n');
  assert.equal(stringify([['a"b"']]), '"a""b"""\r\n');
});

test('a record of one empty field is written as ""', () => {
  assert.equal(stringify([['']]), '""\r\n');
  assert.equal(stringify([[null]]), '""\r\n');
  assert.equal(stringify([['a'], [''], [undefined]], { eol: '\n' }), 'a\n""\n""\n');
  assert.equal(stringify([['', '']]), ',\r\n');
});

test('uses the eol option', () => {
  assert.equal(stringify([['a'], ['b']], { eol: '\n' }), 'a\nb\n');
  assert.equal(stringify([['a'], ['b']], { eol: '\r\n' }), 'a\r\nb\r\n');
  for (const eol of ['\r', ' ', '', '\n\r', null, 1]) {
    assert.throws(() => stringify([['a']], { eol }), TypeError, JSON.stringify(eol));
  }
});

test('uses and validates the delimiter option', () => {
  assert.equal(stringify([['a', 'b;c', 'd,e']], { delimiter: ';' }), 'a;"b;c";d,e\r\n');
  assert.equal(stringify([['a', 'b c']], { delimiter: ' ' }), 'a "b c"\r\n');
  assert.equal(stringify([['a\tb', 'c']], { delimiter: '\t' }), '"a\tb"\tc\r\n');
  for (const delimiter of ['', ';;', '"', '\r', '\n', null, 0]) {
    assert.throws(() => stringify([['a']], { delimiter }), TypeError, JSON.stringify(delimiter));
  }
});

test('writes objects in header order after the header row', () => {
  const rows = [
    { name: 'Ada', age: 36 },
    { age: 41, name: 'Lin, J', extra: 'ignored' },
    { name: 'Bo' },
    ['x', 'y'],
  ];
  assert.equal(
    stringify(rows, { header: ['name', 'age'] }),
    'name,age\r\nAda,36\r\n"Lin, J",41\r\nBo,\r\nx,y\r\n',
  );
});

test('header mode writes the header even without rows', () => {
  assert.equal(stringify([], { header: ['a', 'b'] }), 'a,b\r\n');
  assert.equal(stringify([], { header: [''] }), '""\r\n');
});

test('header names are quoted like fields', () => {
  assert.equal(stringify([{ 'a,b': 1, ' c': 2 }], { header: ['a,b', ' c'], eol: '\n' }), '"a,b"," c"\n1,2\n');
});

test('object rows use own properties only', () => {
  const row = Object.create({ inherited: 'no' });
  row.own = 'yes';
  assert.equal(stringify([row], { header: ['own', 'inherited', 'toString'] }), 'own,inherited,toString\r\nyes,,\r\n');
});

test('rejects invalid headers and rows', () => {
  for (const header of [true, 'a,b', { a: 1 }, 1, [1], [null]]) {
    assert.throws(() => stringify([], { header }), TypeError, JSON.stringify(header));
  }
  assert.throws(() => stringify([null], { header: ['a'] }), TypeError);
  assert.throws(() => stringify(['a'], { header: ['a'] }), TypeError);
  assert.throws(() => stringify([{ a: {} }], { header: ['a'] }), TypeError);
  assert.equal(stringify([['a']], { header: undefined }), 'a\r\n');
  assert.equal(stringify([['a']], { header: false }), 'a\r\n');
});

test('output never starts with a byte order mark', () => {
  assert.equal(stringify([['﻿a', '﻿b']]), '"﻿a",﻿b\r\n');
  assert.equal(stringify([['a'], ['﻿b']]), 'a\r\n﻿b\r\n');
  assert.equal(stringify([['', 'a']], { delimiter: '﻿' }), '""﻿a\r\n');
  assert.equal(stringify([{ a: 1 }], { header: ['﻿a'] }), '"﻿a"\r\n1\r\n');
});

test('round-trips the documented examples', () => {
  const rows = [['a', 'b'], [''], ['', ''], [' x ', 'y"z'], ['multi\nline', 'cr\ronly', 'crlf\r\n']];
  for (const eol of ['\r\n', '\n']) {
    for (const skipEmptyLines of [false, true]) {
      const options = { eol, skipEmptyLines };
      assert.deepEqual(parse(stringify(rows, options), options), rows);
    }
  }
});

test('round-trips header objects', () => {
  const header = ['id', 'note'];
  const rows = [
    { id: '1', note: 'a, "quoted" note' },
    { id: '2', note: '' },
  ];
  assert.deepEqual(parse(stringify(rows, { header }), { header: true }), rows);
});

test('round-trips random rows of strings', () => {
  const rand = random(3);
  const delimiters = [undefined, ';', '\t', ' ', 'a', '﻿', '|'];
  const alphabet = ['a', 'b', ',', ';', '\t', '|', '"', '\r', '\n', ' ', '﻿', '😀'];
