      eol: rand() < 0.5 ? '\r\n' : '\n',
      skipEmptyLines: rand() < 0.5,
    };
    const text = stringify(rows, options);
    assert.deepEqual(parse(text, options), rows, `${JSON.stringify(text)} with ${JSON.stringify(options)}`);
  }
});

